'use strict'

import resource from '../../resource'
import { TILE_WIDTH, TILE_HEIGHT } from '../../constant'
import { Enemy, randomInt, drawImage } from './common'

// Falling rocks of the mountains: one bounces down the screen from the top, over everything, then
// another one starts again from the top. Nothing stops them
const BOULDER = { life: Infinity, contactDamage: 0.5 }
const HOP_STEPS = 20
const HOP_DOWN = TILE_HEIGHT
const HOP_HEIGHT = TILE_HEIGHT / 2
// Sideways drift per step, at random for each hop
const MAX_DRIFT = 1
const MIN_WAIT_STEPS = 20
const MAX_WAIT_STEPS = 120

const STATE_WAITING_TOP = 'waiting_top'
const STATE_FALLING = 'falling'

class Boulder extends Enemy {
  constructor (type, map, random = Math.random) {
    super(type, map.x, map.y - TILE_HEIGHT, BOULDER, random)
    this.restart(map)
  }

  get isActive () {
    return this.state === STATE_FALLING
  }

  get isVulnerable () {
    return false
  }

  // Above the screen, at a random column, for a while
  restart (map) {
    this.setState(STATE_WAITING_TOP)
    this.wait = randomInt(this.random, MIN_WAIT_STEPS, MAX_WAIT_STEPS)
    this.x = map.x + randomInt(this.random, 1, map.width / TILE_WIDTH - 2) * TILE_WIDTH
    this.baseY = map.y - TILE_HEIGHT
    this.y = this.baseY
    this.drift = 0
    this.hops = 0
  }

  act (map) {
    switch (this.state) {
      case STATE_WAITING_TOP:
        if (this.steps >= this.wait) {
          this.setState(STATE_FALLING)
        }
        break
      case STATE_FALLING: {
        const hopStep = this.steps % HOP_STEPS
        if (hopStep === 0) {
          // A new hop: down a tile, sideways at random, staying on the screen
          this.hops++
          this.baseY += HOP_DOWN
          this.drift = randomInt(this.random, -MAX_DRIFT, MAX_DRIFT)
        }
        const x = this.x + this.drift
        if (x >= map.x && x + this.width <= map.x + map.width) {
          this.x = x
        }
        const t = hopStep / HOP_STEPS
        this.y = Math.round(this.baseY - HOP_DOWN + HOP_DOWN * t - Math.sin(Math.PI * t) * HOP_HEIGHT)
        if (this.y > map.y + map.height) {
          this.restart(map)
        }
        break
      }
    }
  }

  drawBody (context) {
    if (this.state !== STATE_FALLING) {
      return
    }
    drawImage(context, resource.getSprite('boulder_move'), this.hops % 2, this.x, this.y, this.width, this.height)
  }
}

export { Boulder }
